WITH valid AS (SELECT *, ROUND(duration_sec, 1) AS duration_sec_rounded FROM web_events WHERE HOUR(event_time) BETWEEN 12 AND 15), remaining_keys AS (SELECT session_id FROM valid EXCEPT ALL SELECT session_id FROM web_events WHERE page <> '/checkout'), verified AS (SELECT s.* FROM valid s INNER JOIN remaining_keys k ON s.session_id = k.session_id), enriched AS (SELECT *, PERCENT_RANK() OVER (PARTITION BY session_id ORDER BY duration_sec_rounded DESC NULLS LAST) AS duration_sec_rounded_percent_rank, RANK() OVER (ORDER BY duration_sec DESC NULLS LAST) AS duration_sec_rank FROM verified), scored AS (SELECT id, session_id, event_type, page, event_time, duration_sec, duration_sec_rounded, duration_sec_rounded_percent_rank, duration_sec_rank, CUME_DIST() OVER (PARTITION BY event_type ORDER BY duration_sec_rank DESC) AS duration_sec_rank_cume_dist, COUNT(duration_sec_rounded) OVER (ORDER BY CAST(event_time AS BIGINT) ASC RANGE BETWEEN 7776000 PRECEDING AND CURRENT ROW) AS duration_sec_rounded_count_90d FROM enriched) SELECT CASE WHEN duration_sec_rounded_percent_rank >= 0.73 THEN 'PREMIUM' ELSE 'STANDARD' END AS duration_sec_rounded_percent_rank_tier, COUNT(CASE WHEN event_type = 'purchase' THEN 1 END) AS purchase_count, MAX(event_time) AS last_seen, SUM(CASE WHEN page = '/checkout' THEN duration_sec_rounded_count_90d ELSE 0 END) AS checkout_duration_sec_rounded_count_90d FROM scored GROUP BY duration_sec_rounded_percent_rank_tier HAVING COUNT(CASE WHEN event_type = 'purchase' THEN 1 END) >= 1 ORDER BY checkout_duration_sec_rounded_count_90d DESC
